// Thaumaturge content registration. Startup scripts run on both sides, which is required
// because wand parts and golem parts are stored on items by registry id.

// Wand parts: one create makes the linked cap/rod ITEM plus the part entry
// behind it (mirroring the mod's ItemWandCap/ItemWandRod structure). The item id
// prefix wand_cap_/wand_rod_ is stripped to form the part id. Assembly and
// sceptre recipes for every cap/rod pairing are generated by Thaumaturge itself
// from the registries -- nothing to add here.
StartupEvents.registry('minecraft:item', event => {
    event.create('example:wand_cap_netherite', 'thaumaturge:wand_cap')
        .costModifier(0.75)
        .specialAspects(['thaumaturge:ignis', 'thaumaturge:perditio'], 0.6)
        .craftCost(12)
        .wandName('Netherite Shod')

    event.create('example:wand_rod_netherite', 'thaumaturge:wand_rod')
        .capacity(200)
        .craftCost(12)
        .primalCharge('thaumaturge:ignis')
        .glow(true)
        .assemblyGate('thaumaturge:rod_silverwood')
        .wandName('Netherite')
})

// Data-only part entries (no item, no auto recipes) are also possible via the
// part registries directly: StartupEvents.registry('thaumaturge:wand_cap', ...)

StartupEvents.registry('thaumaturge:golem_trait', event => {
    event.create('example:aquatic')
    event.create('example:landlocked').opposite('example:aquatic')
})

StartupEvents.registry('thaumaturge:golem_material', event => {
    event.create('example:netherite')
        .health(30).armor(12).damage(5)
        .itemColor(0x4A4348)
        .base('minecraft:netherite_ingot')
        .mechanism('thaumaturge:mechanism_complex')
        .traits(['thaumaturge:heavy', 'thaumaturge:fireproof', 'thaumaturge:blastproof'])
})

StartupEvents.registry('thaumaturge:golem_head', event => {
    event.create('example:diving')
        .traits(['example:aquatic', 'thaumaturge:smart'])
        .component('minecraft:glass')
        .materialBase()
})

// Custom jars: same glass model, your textures, your capacity. The fill renderer,
// label support, tube/phial interactions and Jade tooltip all come along for free.
StartupEvents.registry('minecraft:block', event => {
    event.create('example:mega_jar', 'thaumaturge:jar')
        .capacity(1000)
        .topTexture('example:block/mega_jar_top')
        .sideTexture('example:block/mega_jar_side')
        .displayName('Mega Warded Jar')
})
